    n: 74,
    title: "Two Paths for A.I.",
    author: "Joshua Rothman",
    venue: "The New Yorker",
    year: 2025,
    url: "https://www.newyorker.com/culture/open-questions/two-paths-for-ai",
    mins: 14,
    kind: "essay",
